const raw = $input.first().json;
const body = raw.body || raw;

// AJUSTE: substitua pelos nomes reais dos campos do checkout
const evento = String(body.evento || body.event || body.status || body.tipo || '').toLowerCase();
const order_id = String(body.order_id || body.id || body.pedido_id || body.orderId || '');
const telefone = String(body.telefone || body.phone || body.whatsapp || body.celular || '').replace(/\D/g, '');
const nome = String(body.nome || body.name || body.cliente_nome || body.customer_name || '');
const email = String(body.email || body.customer_email || '');
const produto_id = String(body.produto_id || body.product_id || body.productId || '');
const valor = parseFloat(String(body.valor || body.amount || body.price || body.total || '0').replace(',', '.')) || 0;
// AJUSTE: nome da instancia WhatsApp do tenant na Evolution API
const instancia = String(body.instancia || body.instance || 'SUA_INSTANCIA_WA');

if (!order_id || !telefone) return [];

return [{ json: { evento, order_id, telefone, nome, email, produto_id, valor, instancia } }];

const pedido = $('Extrair Dados Checkout').first().json;
const config = $input.first().json;

const primeiroNome = (pedido.nome || 'cliente').split(' ')[0];
const evoUrl = config.evo_api_url || 'https://evo.upviaagentes.com';
const evoKey = config.evo_api_key || '';
const instanciaWA = config.instancia_whatsapp || pedido.instancia;
const telDono = config.telefone_proprietario || '';
const empresa = config.nome_empresa || '';

// AJUSTE: personalize a mensagem e substitua LINK_DO_GRUPO_WA pelo link real do grupo
const msg = 'Ola ' + primeiroNome + '! ??\n\nSua compra foi confirmada com sucesso!\n\nPara acessar seu conteudo exclusivo, entre no nosso grupo pelo link abaixo:\n\n?? LINK_DO_GRUPO_WA ??\n\nQualquer duvida e so me chamar aqui. Bom aprendizado! ??';

return [{
  json: {
    order_id: pedido.order_id,
    telefone: pedido.telefone,
    nome: pedido.nome,
    valor: pedido.valor,
    evo_api_url: evoUrl,
    evo_api_key: evoKey,
    instancia_whatsapp: instanciaWA,
    telefone_proprietario: telDono,
    nome_empresa: empresa,
    mensagem_pos_compra: msg,
    remoteJid: pedido.telefone + '@s.whatsapp.net'
  }
}];

