const raw = $input.first().json;
const body = raw.body || raw;

const evento = (body?.event || '').toLowerCase();
const fromMe = body?.data?.key?.fromMe ?? false;
const remoteJid = body?.data?.key?.remoteJid || '';
const messageId = body?.data?.key?.id || '';
const instance = body?.instance || body?.instanceName || '';

const msg = body?.data?.message || {};
const text = (msg.conversation || msg.extendedTextMessage?.text || '').trim();
const pushName = body?.data?.pushName || '';

const isMessage = evento.includes('messages');
const isGroup = remoteJid.endsWith('@g.us');
const hasText = !!text;

if (!isMessage || isGroup || !hasText || fromMe) return [];

const telefone = remoteJid.replace(/@s\.whatsapp\.net$/, '');

return [{
  json: {
    instance,
    remoteJid,
    telefone,
    text,
    pushName,
    messageId
  }
}];

const filtro = $('Filtro Mensagem WA').first().json;
const config = $input.first().json;

const text = (filtro.text || '').toLowerCase().trim();

// Detectar opcao pelo que o usuario digitou
let opcao = 0; // 0 = mostrar menu
if (text === '1' || text.includes('status') || text.includes('pedido') || text.includes('rastreio') || text.includes('entrega')) {
  opcao = 1;
} else if (text === '2' || text.includes('duvida') || text.includes('pergunta') || text.includes('como') || text.includes('funciona')) {
  opcao = 2;
} else if (text === '3' || text.includes('problema') || text.includes('acesso') || text.includes('tecnico') || text.includes('erro') || text.includes('nao consigo') || text.includes('nao abre')) {
  opcao = 3;
} else if (text === '4' || text.includes('humano') || text.includes('atendente') || text.includes('pessoa') || text.includes('falar com')) {
  opcao = 4;
}

return [{
  json: {
    remoteJid: filtro.remoteJid,
    telefone: filtro.telefone,
    text: filtro.text,
    pushName: filtro.pushName,
    instance: filtro.instance,
    opcao,
    evo_api_url: config.evo_api_url || 'https://evo.upviaagentes.com',
    evo_api_key: config.evo_api_key || '',
    instancia_whatsapp: config.instancia_whatsapp || filtro.instance,
    telefone_proprietario: config.telefone_proprietario || '',
    nome_empresa: config.nome_empresa || 'nos',
    nome_atendente: config.nome_atendente_ia || 'Assistente'
  }
}];

